PASSPHRASE = "benchmark-passphrase"


def derive_key(passphrase: str) -> bytes:
    return hashlib.sha256(passphrase.encode("utf-8")).digest()


def xor_transform(data: bytes, key: bytes) -> bytes:
    return bytes(value ^ key[index % len(key)] for index, value in enumerate(data))


def ensure_sample_data(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    if not SAMPLE_FILE.exists():
        SAMPLE_FILE.write_text(
            "Representative controlled benchmark data.\n",
            encoding="utf-8",
        )


def encrypt_file_copy(source: Path, key: bytes) -> dict:
    encrypted_path = source.with_name(source.name + ".enc")
    plaintext = source.read_bytes()
    encrypted_path.write_bytes(xor_transform(plaintext, key))
    return {
        "source": str(source),
        "encrypted_copy": str(encrypted_path),
        "key_sha256": hashlib.sha256(key).hexdigest(),
    }


def write_ransom_note(directory: Path, note: str) -> None:
