}
DEMO_NOTE = (
    "This is a controlled, non-destructive encryption demonstration.\n"
    "Original files are preserved. Encrypted copies use the .demo.enc suffix.\n"
)


def generate_key(filename: str, salt: str) -> bytes:
    return hashlib.sha256(f"{filename}:{salt}".encode("utf-8")).digest()


def xor_transform(data: bytes, key: bytes) -> bytes:
    return bytes(value ^ key[index % len(key)] for index, value in enumerate(data))


def ensure_demo_environment() -> None:
