    for filename, content in SAMPLE_FILES.items():
        path = DATA_DIR / filename
        if not path.exists():
            path.write_bytes(content)


def encrypt_file_copy(source: Path, destination: Path, key: bytes) -> None:
    destination.write_bytes(xor_transform(source.read_bytes(), key))


def write_controlled_key_sink(metadata: dict) -> None:
    KEY_SINK.write_text(
        json.dumps(metadata, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


