    marker = {
        "type": "demo_persistence_record",
        "enabled": True,
        "directory": str(directory),
        "action": "rerun controlled encryption demonstration",
    }
    PERSISTENCE_MARKER.write_text(
        json.dumps(marker, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


