    }

    for source in sorted(target.iterdir()):
        if not source.is_file():
            continue
        if source.name.endswith(".demo.enc") or source.name == NOTE_PATH.name:
            continue

        key = generate_key(source.name, salt)
        destination = source.with_name(source.name + ".demo.enc")
        encrypt_file_copy(source, destination, key)

        metadata["files"].append(
            {
                "file_name": source.name,
                "encrypted_copy": destination.name,
                "key": key.hex(),
            }
        )

    create_recovery_note(note)
    write_controlled_key_sink(metadata)
    install_demo_persistence(target)


