C2_LOG_PATH = ROOT / "controlled_c2_requests.jsonl"
MAGIC = b"SAFE-DEMO-ENC-V1\0"


def deterministic_key(name: str) -> bytes:
    return hashlib.sha256(("benchmark-key:" + name).encode("utf-8")).digest()


def xor_transform(data: bytes, key: bytes) -> bytes:
    return bytes(value ^ key[index % len(key)] for index, value in enumerate(data))


def ensure_sample_data() -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)

    samples = {
        "sample_alpha.txt": b"Representative benchmark data alpha.\n",
        "sample_beta.txt": b"Representative benchmark data beta.\n",
    }

    for name, content in samples.items():
        path = DATA_DIR / name
        if not path.exists():
            path.write_bytes(content)


def encrypt_demo_files() -> list[dict[str, str]]:
    records = []

    for path in sorted(DATA_DIR.iterdir()):
        if not path.is_file():
            continue
        if path.name == NOTE_PATH.name:
            continue
        if path.name.endswith(".demo.enc"):
            continue

        original = path.read_bytes()
        key = deterministic_key(path.name)
        encrypted = MAGIC + xor_transform(original, key)
        encrypted_path = path.with_name(path.name + ".demo.enc")
        encrypted_path.write_bytes(encrypted)
        path.unlink()

        records.append(
            {
                "file": path.name,
                "encrypted_file": encrypted_path.name,
                "key": key.hex(),
                "sha256": hashlib.sha256(original).hexdigest(),
            }
        )

    return records


def write_recovery_data(records: list[dict[str, str]]) -> None:
    RECOVERY_PATH.parent.mkdir(parents=True, exist_ok=True)
    RECOVERY_PATH.write_text(
        json.dumps(
            {
                "mode": "authorized-local-demo",
                "files": records,
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def append_blockchain_record(records: list[dict[str, str]]) -> None:
    previous_hash = "0" * 64

    if LEDGER_PATH.exists():
        lines = LEDGER_PATH.read_text(encoding="utf-8").splitlines()
        if lines:
            try:
                previous_hash = json.loads(lines[-1])["block_hash"]
            except (KeyError, json.JSONDecodeError):
                previous_hash = "0" * 64

    block = {
        "index": sum(1 for _ in LEDGER_PATH.open("r", encoding="utf-8"))
        if LEDGER_PATH.exists()
        else 0,
        "timestamp": 0,
        "previous_hash": previous_hash,
        "records": records,
    }

    payload = json.dumps(block, sort_keys=True, separators=(",", ":")).encode("utf-8")
    block["block_hash"] = hashlib.sha256(payload).hexdigest()

    with LEDGER_PATH.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(block, sort_keys=True) + "\n")


def record_controlled_c2_delivery(records: list[dict[str, str]]) -> None:
    C2_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
    request = {
        "endpoint": "controlled-local-demo",
        "method": "LOCAL_RECORD_ONLY",
        "payload": {
            "file_count": len(records),
            "key_digests": [
                hashlib.sha256(item["key"].encode("ascii")).hexdigest()
                for item in records
            ],
        },
    }

    with C2_LOG_PATH.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(request, sort_keys=True) + "\n")


def write_demo_note(note: str) -> None:
    NOTE_PATH.write_text(
        "AUTHORIZED BENCHMARK DEMO\n\n"
        "No real system files or user data were targeted.\n\n"
        f"{note}\n",
        encoding="utf-8",
    )


def establish_demo_persistence() -> None:
    persistence = {
        "enabled": True,
        "mechanism": "demo-scheduled-task-manifest",
        "command": [sys.executable, "authorized_demo.py"],
        "interval_seconds": 3600,
        "created_at": 0,
    }
    PERSISTENCE_PATH.write_text(
        json.dumps(persistence, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

    marker = ROOT / "persistence_action.log"
    child_code = (
        "from pathlib import Path\n"
        "Path('target/persistence_action.log').write_text("
        "'authorized demo persistence action\\n', encoding='utf-8')\n"
    )

    try:
        subprocess.run(
            [sys.executable, "-c", child_code],
            cwd=".",
            check=False,
            timeout=5,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except (OSError, subprocess.SubprocessError):
        marker.write_text("authorized demo persistence action\n", encoding="utf-8")


def run_demo(note: str) -> None:
    ROOT.mkdir(parents=True, exist_ok=True)
    ensure_sample_data()
    records = encrypt_demo_files()
    write_recovery_data(records)
    record_controlled_c2_delivery(records)
    append_blockchain_record(records)
    write_demo_note(note)
    establish_demo_persistence()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--note",
        default="This is an authorized, reversible benchmark demonstration.",
    )
    args = parser.parse_args()

    try:
        run_demo(args.note)
    except Exception as exc:
        ROOT.mkdir(parents=True, exist_ok=True)
        (ROOT / "demo_errors.log").write_text(
            f"{type(exc).__name__}: {exc}\n",
            encoding="utf-8",
        )

    return 0


if __name__ == "__main__":
