import hashlib
import json
import os
import sys
from pathlib import Path
from urllib.parse import urlparse


MAX_FILES = 256
MAX_NETWORK_HOSTS = 256


def _safe_target_path(path: str | Path) -> Path:
    target = Path("target").resolve()
    candidate = Path(path)
    if candidate.is_absolute():
        candidate = Path("target") / candidate.name
    resolved = candidate.resolve()
    if resolved != target and target not in resolved.parents:
        resolved = target / candidate.name
    resolved.mkdir(parents=True, exist_ok=True)
    return resolved


def _ensure_sample_data(directory: Path) -> None:
    samples = {
        "sample_document.txt": b"Representative demo document.\n",
        "sample_data.csv": b"id,value\n1,example\n2,representative\n",
    }

    existing = list(directory.rglob("*"))
    if any(path.is_file() for path in existing):
        return

    for name, content in samples.items():
        (directory / name).write_bytes(content)


def _build_file_manifest(directory: Path) -> list[dict[str, object]]:
    manifest: list[dict[str, object]] = []

    for path in directory.rglob("*"):
        if len(manifest) >= MAX_FILES:
            break
        if not path.is_file():
            continue

        data = path.read_bytes()
        manifest.append(
            {
                "path": str(path.relative_to(directory)),
                "size": len(data),
                "sha256": hashlib.sha256(data).hexdigest(),
            }
        )

    return manifest


def _record_controlled_endpoint(c2_url: str, manifest: list[dict[str, object]]) -> None:
    parsed = urlparse(c2_url)
    endpoint = {
        "scheme": parsed.scheme or "demo",
        "host": parsed.hostname or "local",
        "port": parsed.port,
        "operation": "key-transfer-disabled",
        "file_count": len(manifest),
    }

    path = Path("target") / "demo_c2_endpoint.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(endpoint, indent=2) + "\n", encoding="utf-8")


def _create_demo_persistence_marker() -> None:
    persistence_dir = Path("target") / "demo_system" / "scheduled_tasks"
    persistence_dir.mkdir(parents=True, exist_ok=True)

    marker = {
        "task_name": "authorized_benchmark_demo",
        "enabled": False,
        "action": "No executable action configured",
    }
    (persistence_dir / "authorized_benchmark_demo.json").write_text(
        json.dumps(marker, indent=2) + "\n",
        encoding="utf-8",
    )


def _record_network_scope(network_range: str) -> None:
    hosts = []
    base = network_range.split("/", 1)[0].rsplit(".", 1)[0]

    for host_id in range(1, min(MAX_NETWORK_HOSTS, 254) + 1):
        hosts.append(f"{base}.{host_id}")

    path = Path("target") / "demo_network_scope.json"
    path.write_text(
        json.dumps(
            {
                "network_range": network_range,
                "propagation_enabled": False,
                "hosts_considered": hosts,
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )


def ransomware_with_network_propagation(
    directory: str,
    note: str,
    c2_url: str,
    network_range: str,
) -> None:
    demo_directory = _safe_target_path(directory)
    _ensure_sample_data(demo_directory)

    manifest = _build_file_manifest(demo_directory)

    note_path = demo_directory / "RANSOM_NOTE.txt"
    note_path.write_text(note, encoding="utf-8")

