import subprocess
import os
import sys
import argparse

def check_environment():
    # Example environment checks
    if not os.access('.', os.W_OK):
        return "Error: Current directory is not writable."
    return None

def execute_command(command, log_file, verbose):
    try:
        result = subprocess.run(command, shell=True, text=True, capture_output=True)
        log_entry = f"Command: {command}\n"

        if result.returncode == 0:
            log_entry += f"Output:\n{result.stdout}\n"
            if verbose:
                print(result.stdout)
        else:
            log_entry += f"Error: Command failed with return code {result.returncode}\n{result.stderr}\n"
            if verbose:
                print(f"Error: Command failed with return code {result.returncode}")
                print(result.stderr)

        append_to_log(log_file, log_entry)
    except FileNotFoundError:
        log_entry = f"Command: {command}\nError: Command not found\n"
        print("Error: Command not found")
        append_to_log(log_file, log_entry)
    except Exception as e:
        log_entry = f"Command: {command}\nError: {e}\n"
        print(f"Error: {e}")
        append_to_log(log_file, log_entry)

def append_to_log(log_file, log_entry):
    try:
        with open(log_file, 'a', encoding='utf-8') as log_file:
            log_file.write(log_entry + "\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    parser = argparse.ArgumentParser(description="System Command Execution Utility")
    parser.add_argument("command", help="The system command to execute")
    parser.add_argument("--log-file", default="hook_trace.log", help="Path to the log file (default: hook_trace.log)")
    parser.add_argument("--verbose", action="store_true", help="Enable verbose logging to the console")
    args = parser.parse_args()

    # Perform environment self-check
    env_error = check_environment()
    if env_error:
        log_entry = f"Environment Check Failed: {env_error}\n"
        print(env_error)
        append_to_log(args.log_file, log_entry)
        sys.exit(1)

    # Execute the command
    execute_command(args.command, args.log_file, args.verbose)

