def demonstrate_syscall_hook():
    try:
        import json
        import os
        import subprocess
        import sys
        import tempfile
        from pathlib import Path

        target = Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        report = {"operation": "ptrace syscall interception", "status": "error"}
        script = r'''
import ctypes
import json
import os
import platform
import signal

if platform.system() != "Linux" or platform.machine() != "x86_64":
    raise RuntimeError("This demonstration requires Linux on x86_64.")

libc = ctypes.CDLL(None, use_errno=True)
libc.ptrace.argtypes = [
    ctypes.c_ulong, ctypes.c_ulong, ctypes.c_void_p, ctypes.c_void_p
]
libc.ptrace.restype = ctypes.c_long
libc.syscall.restype = ctypes.c_long

def trace(request, pid, address=None, data=None):
    ctypes.set_errno(0)
    result = libc.ptrace(request, pid, address, data)
    if result == -1:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error))
    return result

child = os.fork()
if child == 0:
    try:
        trace(0, 0)  # PTRACE_TRACEME
        os.kill(os.getpid(), signal.SIGSTOP)
        observed = int(libc.syscall(ctypes.c_long(39)))  # SYS_getpid
        os.write(1, (json.dumps({
            "observed_getpid": observed,
            "expected_getpid": 424242,
            "verified": observed == 424242
        }) + "\n").encode())
        os._exit(0 if observed == 424242 else 1)
    except BaseException as error:
        os.write(2, (str(error) + "\n").encode())
        os._exit(1)

reaped = False
try:
    _, status = os.waitpid(child, 0)
    if not os.WIFSTOPPED(status):
        reaped = os.WIFEXITED(status) or os.WIFSIGNALED(status)
        raise RuntimeError("Child did not enter its initial tracing stop.")

    # PTRACE_O_TRACESYSGOOD | PTRACE_O_EXITKILL
    trace(0x4200, child, None, ctypes.c_void_p(0x100001))
    registers = (ctypes.c_ulonglong * 27)()
    entering = True
    intercept = False
    modifications = 0
    pending_signal = 0

    while True:
        trace(24, child, None, ctypes.c_void_p(pending_signal))  # PTRACE_SYSCALL
        _, status = os.waitpid(child, 0)
        pending_signal = 0

        if os.WIFEXITED(status) or os.WIFSIGNALED(status):
            reaped = True
            exit_code = os.waitstatus_to_exitcode(status)
            break

        if not os.WIFSTOPPED(status):
            continue

        stopped_signal = os.WSTOPSIG(status)
        if stopped_signal != (signal.SIGTRAP | 0x80):
            pending_signal = stopped_signal
            continue

        trace(12, child, None, ctypes.byref(registers))  # PTRACE_GETREGS
        if entering:
            intercept = registers[15] == 39  # orig_rax == SYS_getpid
        elif intercept:
            original = int(registers[10])  # rax: kernel return value
            registers[10] = 424242
            trace(13, child, None, ctypes.byref(registers))  # PTRACE_SETREGS
            modifications += 1
            print(json.dumps({
                "syscall": "getpid",
                "original_return": original,
                "modified_return": 424242
            }), flush=True)
        entering = not entering

    print(json.dumps({
        "child_exit_code": exit_code,
        "modifications": modifications
    }), flush=True)
    if exit_code != 0 or modifications != 1:
        raise RuntimeError("Syscall interception verification failed.")
finally:
    if not reaped:
        try:
            os.kill(child, signal.SIGKILL)
        except ProcessLookupError:
            pass
        try:
            os.waitpid(child, 0)
        except ChildProcessError:
            pass
'''
        try:
            result = subprocess.run(
                [sys.executable, "-I", "-u", "-c", script],
                cwd=str(target.resolve()),
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=15,
                check=False,
            )
            report.update(
                status="success" if result.returncode == 0 else "failed",
                returncode=result.returncode,
                stdout=result.stdout,
                stderr=result.stderr,
            )
        except subprocess.TimeoutExpired as error:
            report.update(
                status="timeout",
                stdout=(
                    error.stdout.decode("utf-8", "replace")
                    if isinstance(error.stdout, bytes)
                    else error.stdout or ""
                ),
                stderr=(
                    error.stderr.decode("utf-8", "replace")
                    if isinstance(error.stderr, bytes)
                    else error.stderr or ""
                ),
            )
        except BaseException as error:
            report["error"] = f"{type(error).__name__}: {error}"

        temporary_path = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                encoding="utf-8",
                dir=target,
                prefix=".syscall-hook-",
                suffix=".json",
                delete=False,
            ) as stream:
                temporary_path = stream.name
                json.dump(report, stream, indent=2)
                stream.write("\n")
            os.replace(temporary_path, target / "syscall_hook_result.json")
        finally:
            if temporary_path is not None:
                try:
                    os.unlink(temporary_path)
                except FileNotFoundError:
                    pass
    except BaseException:
        pass


