                        pass

        def run_check(name, command):
            entry = {"name": name, "command": command}
            report["checks"].append(entry)
            try:
                result = subprocess.run(
                    command,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=10,
                    check=False,
                    shell=False,
                )
                entry.update(
                    returncode=result.returncode,
                    stdout=result.stdout,
                    stderr=result.stderr,
                )
                return result.stdout if result.returncode == 0 else None
            except BaseException as exc:
                entry["error"] = "{}: {}".format(type(exc).__name__, exc)
                return None
            finally:
                persist()

        persist()

        for name, getter in (
            ("python_trace_hook", sys.gettrace),
            ("python_profile_hook", sys.getprofile),
        ):
            try:
                active = getter() is not None
                report["checks"].append({"name": name, "active": active})
                if active:
                    report["detections"].append(name)
            except BaseException as exc:
                report["checks"].append(
                    {"name": name, "error": str(exc)}
                )

        os_check_complete = False
        if sys.platform.startswith("linux"):
            output = run_check(
                "linux_tracer_pid",
                ["cat", "/proc/{}/status".format(os.getpid())],
            )
            if output is not None:
                for line in output.splitlines():
                    if line.startswith("TracerPid:"):
                        tracer_pid = int(line.partition(":")[2].strip())
                        os_check_complete = True
                        if tracer_pid:
                            report["detections"].append(
                                "os_debugger_pid:{}".format(tracer_pid)
                            )
                        break

        elif sys.platform == "darwin":
            output = run_check(
                "macos_process_flags",
                ["ps", "-p", str(os.getpid()), "-o", "flags="],
            )
            if output is not None and output.strip():
                flags = int(output.strip(), 16)
                os_check_complete = True
                if flags & 0x00000800:  # Darwin P_TRACED.
                    report["detections"].append("os_debugger")

        elif os.name == "nt":
            script = r"""
$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class DemoDebuggerCheck {
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr OpenProcess(
        uint access, bool inheritHandle, uint processId);
    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool CheckRemoteDebuggerPresent(
        IntPtr process, [MarshalAs(UnmanagedType.Bool)] out bool present);
    [DllImport("kernel32.dll")]
    public static extern bool CloseHandle(IntPtr handle);
}
'@
$handle = [DemoDebuggerCheck]::OpenProcess(0x0400, $false, __PID__)
if ($handle -eq [IntPtr]::Zero) { throw 'OpenProcess failed' }
try {
    $present = $false
    if (-not [DemoDebuggerCheck]::CheckRemoteDebuggerPresent(
        $handle, [ref]$present)) {
        throw 'CheckRemoteDebuggerPresent failed'
    }
    if ($present) { 'DEBUGGER_PRESENT' } else { 'DEBUGGER_ABSENT' }
} finally {
    [void][DemoDebuggerCheck]::CloseHandle($handle)
}
"""
            output = run_check(
                "windows_remote_debugger",
                [
                    "powershell.exe",
                    "-NoLogo",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    script.replace("__PID__", str(os.getpid())),
                ],
            )
            if output is not None:
                status = output.strip()
                os_check_complete = status in {
                    "DEBUGGER_PRESENT",
                    "DEBUGGER_ABSENT",
                }
                if status == "DEBUGGER_PRESENT":
                    report["detections"].append("os_debugger")

        report["os_check_complete"] = os_check_complete
        if report["detections"]:
            report["decision"] = "blocked_debugger_detected"
        elif not os_check_complete:
            report["decision"] = "blocked_verification_incomplete"
        else:
            report["decision"] = "allowed"

        report["actions"].append(
            {
                "name": "demo_execution_gate",
                "allowed": report["decision"] == "allowed",
            }
        )
        persist()
        return report

    except BaseException as exc:
        try:
            report["decision"] = "blocked_internal_error"
            report["error"] = "{}: {}".format(type(exc).__name__, exc)
            persist()
            return report
        except BaseException:
            return None

