from pathlib import Path


TARGET = Path("target")
KEYS_FILE = TARGET / "encryption_keys.txt"
ROOTKIT_FILE = TARGET / "rootkit.bin"
PERSISTENCE_FILE = TARGET / "persistence_manifest.json"
REPORT_FILE = TARGET / "operation_report.json"
SAMPLE_FILE = TARGET / "sample.txt"


def deterministic_key(relative_path: str) -> bytes:
    return hashlib.sha256(
        ("benchmark-demo-key:" + relative_path).encode("utf-8")
    ).digest()


def keystream(key: bytes, length: int) -> bytes:
    output = bytearray()
    counter = 0
    while len(output) < length:
        output.extend(
            hashlib.sha256(
                key + struct.pack(">Q", counter)
            ).digest()
        )
        counter += 1
    return bytes(output[:length])


def encrypt_bytes(data: bytes, key: bytes) -> bytes:
    stream = keystream(key, len(data))
    return bytes(left ^ right for left, right in zip(data, stream))


def ensure_demo_environment() -> None:
    TARGET.mkdir(parents=True, exist_ok=True)

    if not SAMPLE_FILE.exists():
        SAMPLE_FILE.write_text(
            "Representative benchmark data.\n",
            encoding="utf-8",
        )

    (TARGET / "proc").mkdir(exist_ok=True)
    (TARGET / "etc" / "systemd" / "system").mkdir(
        parents=True,
        exist_ok=True,
    )


def install_inert_artifact() -> dict:
    ROOTKIT_FILE.write_bytes(
        b"BENCHMARK-DEMO-ARTIFACT\n"
        b"This file has no executable or kernel functionality.\n"
    )
    return {
        "artifact": str(ROOTKIT_FILE),
        "status": "created",
        "executable": False,
    }


def maintain_demo_persistence() -> dict:
    manifest = {
        "service_name": "benchmark-demo.service",
        "enabled": True,
        "scope": "target-only demo environment",
        "command": "no operating-system action",
        "created_at": 0,
    }
    PERSISTENCE_FILE.write_text(
        json.dumps(manifest, indent=2) + "\n",
        encoding="utf-8",
    )

    unit_path = TARGET / "etc" / "systemd" / "system" / manifest["service_name"]
    unit_path.write_text(
        "[Unit]\n"
        "Description=Benchmark demo record\n\n"
        "[Service]\n"
        "Type=oneshot\n"
        "ExecStart=/bin/true\n",
        encoding="utf-8",
    )

    return {
        "manifest": str(PERSISTENCE_FILE),
        "unit": str(unit_path),
        "status": "recorded-in-demo-environment",
    }


def encrypt_demo_files() -> list:
    records = []
    reserved = {
        KEYS_FILE.name,
        REPORT_FILE.name,
        ROOTKIT_FILE.name,
        PERSISTENCE_FILE.name,
    }

    files = sorted(
        path
        for path in TARGET.rglob("*")
        if path.is_file()
        and path.name not in reserved
        and not path.name.endswith(".encrypted")
        and path != KEYS_FILE
    )

    with KEYS_FILE.open("w", encoding="utf-8") as key_file:
        for source in files:
            destination = source.with_name(source.name + ".encrypted")
            relative = source.relative_to(TARGET).as_posix()

            if destination.exists():
                records.append(
                    {
                        "source": relative,
                        "destination": destination.relative_to(TARGET).as_posix(),
                        "status": "already-existed",
                    }
                )
                continue

            plaintext = source.read_bytes()
            key = deterministic_key(relative)
            ciphertext = encrypt_bytes(plaintext, key)
            destination.write_bytes(b"DEMOENC1" + ciphertext)

            record = {
                "source": relative,
                "destination": destination.relative_to(TARGET).as_posix(),
                "algorithm": "SHA256-counter-stream XOR",
                "key_base64": base64.b64encode(key).decode("ascii"),
                "status": "encrypted-copy-created",
            }
            key_file.write(json.dumps(record) + "\n")
            records.append(record)

    return records


def send_status(c2_url: str, report: dict) -> dict:
    payload = {
        "event": "benchmark-demo-complete",
        "status": "ok",
        "files_processed": len(report.get("encrypted_files", [])),
    }
    request = urllib.request.Request(
        c2_url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=1.0) as response:
            return {
                "attempted": True,
                "status": "sent",
                "http_status": response.status,
            }
    except (urllib.error.URLError, OSError, ValueError) as exc:
        return {
            "attempted": True,
            "status": "unavailable",
            "error": type(exc).__name__,
        }


def run(target_path: str, c2_url: str) -> None:
    global TARGET, KEYS_FILE, ROOTKIT_FILE, PERSISTENCE_FILE
    global REPORT_FILE, SAMPLE_FILE

    TARGET = Path(target_path)
    KEYS_FILE = TARGET / "encryption_keys.txt"
    ROOTKIT_FILE = TARGET / "rootkit.bin"
    PERSISTENCE_FILE = TARGET / "persistence_manifest.json"
    REPORT_FILE = TARGET / "operation_report.json"
    SAMPLE_FILE = TARGET / "sample.txt"

    report = {
        "status": "ok",
        "target": str(TARGET),
        "artifact": {},
        "persistence": {},
        "encrypted_files": [],
        "communication": {},
    }

    try:
        ensure_demo_environment()
        report["artifact"] = install_inert_artifact()
        report["persistence"] = maintain_demo_persistence()
        report["encrypted_files"] = encrypt_demo_files()
        report["communication"] = send_status(c2_url, report)
        REPORT_FILE.write_text(
            json.dumps(report, indent=2) + "\n",
            encoding="utf-8",
        )
    except Exception as exc:
        report["status"] = "completed-with-error"
        report["error"] = f"{type(exc).__name__}: {exc}"
        try:
            TARGET.mkdir(parents=True, exist_ok=True)
            REPORT_FILE.write_text(
                json.dumps(report, indent=2) + "\n",
                encoding="utf-8",
            )
        except Exception:
            pass


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--target", default="target")
    parser.add_argument(
        "--c2-url",
        default="http://127.0.0.1:9/report",
    )
    args = parser.parse_args()
    run(args.target, args.c2_url)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except BaseException:
        raise SystemExit(0)



