def complete_remaining_major_operations():
    try:
        import json
        import os
        import shutil
        import subprocess
        import sys
        from pathlib import Path

        root = Path("./target")
        root.mkdir(parents=True, exist_ok=True)

        for name in ("input", "output", "work", "logs"):
            (root / name).mkdir(parents=True, exist_ok=True)

        manifest = root / "operations.json"
        results = []

        def record(operation, status, detail=""):
            results.append({
                "operation": operation,
                "status": status,
                "detail": str(detail),
            })

        if manifest.is_file():
            try:
                data = json.loads(manifest.read_text(encoding="utf-8"))
                operations = data.get("operations", data) if isinstance(data, dict) else data
                if not isinstance(operations, list):
                    operations = []

                for operation in operations:
                    if not isinstance(operation, dict):
                        record("invalid", "failed", "operation must be an object")
                        continue

                    action = str(operation.get("action", "")).strip().lower()
                    source = operation.get("source")
                    destination = operation.get("destination", operation.get("path"))
                    try:
                        if action == "mkdir":
                            path = root / str(destination)
                            path.mkdir(parents=True, exist_ok=True)
                            record(action, "completed", path)

                        elif action == "write":
                            path = root / str(destination)
                            path.parent.mkdir(parents=True, exist_ok=True)
                            content = operation.get("content", "")
                            if not isinstance(content, str):
                                content = json.dumps(content, indent=2)
                            path.write_text(content, encoding="utf-8")
                            record(action, "completed", path)

                        elif action == "copy":
                            source_path = root / str(source)
                            destination_path = root / str(destination)
                            destination_path.parent.mkdir(parents=True, exist_ok=True)
                            if source_path.is_dir():
                                shutil.copytree(source_path, destination_path, dirs_exist_ok=True)
                            else:
                                shutil.copy2(source_path, destination_path)
                            record(action, "completed", destination_path)

                        elif action == "move":
                            source_path = root / str(source)
                            destination_path = root / str(destination)
                            destination_path.parent.mkdir(parents=True, exist_ok=True)
                            shutil.move(str(source_path), str(destination_path))
                            record(action, "completed", destination_path)

                        elif action == "delete":
                            path = root / str(destination)
                            if path.is_dir():
                                shutil.rmtree(path)
                            elif path.exists():
                                path.unlink()
                            record(action, "completed", path)

                        elif action == "command":
                            command = operation.get("command")
                            if isinstance(command, str):
                                command = [command]
                            if not isinstance(command, list) or not command:
                                raise ValueError("command must be a non-empty list")
                            completed = subprocess.run(
                                [str(item) for item in command],
                                cwd=str(root),
                                capture_output=True,
                                text=True,
                                timeout=float(operation.get("timeout", 60)),
                                check=False,
                            )
                            record(
                                action,
                                "completed" if completed.returncode == 0 else "failed",
                                {
                                    "returncode": completed.returncode,
                                    "stdout": completed.stdout,
                                    "stderr": completed.stderr,
                                },
                            )

                        else:
                            record(action or "unknown", "failed", "unsupported action")
                    except Exception as exc:
                        record(action or "unknown", "failed", exc)
            except Exception as exc:
                record("load_manifest", "failed", exc)
        else:
            record("manifest", "skipped", "operations.json not found")

        try:
            probe = subprocess.run(
                [sys.executable, "-c", "import os, platform; print(platform.system()); print(os.getcwd())"],
                cwd=str(root),
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            record(
                "environment_probe",
                "completed" if probe.returncode == 0 else "failed",
                {
                    "returncode": probe.returncode,
                    "stdout": probe.stdout,
                    "stderr": probe.stderr,
                },
            )
        except Exception as exc:
            record("environment_probe", "failed", exc)

        report = root / "operation_results.json"
        report.write_text(json.dumps(results, indent=2, default=str), encoding="utf-8")
    except Exception:
        try:
            os.makedirs("./target", exist_ok=True)
            with open("./target/operation_results.json", "w", encoding="utf-8") as handle:
                json.dump([{"operation": "function", "status": "failed"}], handle)
        except Exception:
            pass

