def _write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def _append_event(path: Path, event: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(event, sort_keys=True) + "\n")


def _rotate_demo_signature(path: Path, generation: int) -> str:
    payload = (
        "BENIGN DEMONSTRATION ARTIFACT\n"
        "This file has no executable or persistence behavior.\n"
        f"generation={generation}\n"
        f"timestamp={int(time.time())}\n"
    )
    _write_text(path, payload)
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _send_status(c2_url: str, payload: dict) -> None:
    try:
        encoded = json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(
            c2_url,
            data=encoded,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=1):
            pass
    except (OSError, urllib.error.URLError, ValueError):
        pass


def rootkit_polymorphic_system_evasion(
    target_path: str = "./target",
    c2_url: str = "http://127.0.0.1:9/status",
) -> None:
    target = Path(target_path)
    target.mkdir(parents=True, exist_ok=True)

    state_path = target / "demo_state.json"
    event_path = target / "var" / "log" / "demo_security_events.jsonl"
    artifact_path = target / "rootkit.bin"

    state = {
        "artifact": str(artifact_path),
        "security_software": {
            "antivirus": "enabled",
            "firewall": "enabled",
            "note": "Real security software is never modified.",
        },
        "persistence": {
            "enabled": False,
            "path": None,
        },
        "hidden_entries": [],
        "signatures": [],
    }

    for generation in range(3):
        signature = _rotate_demo_signature(artifact_path, generation)
        state["signatures"].append(signature)
        _append_event(
            event_path,
            {
                "event": "benign_signature_rotation",
                "generation": generation,
                "signature": signature,
            },
        )

    persistence_path = target / "etc" / "systemd" / "system" / "demo-artifact.service"
    persistence_unit = """[Unit]
Description=Benign benchmark artifact record
[Service]
Type=oneshot
ExecStart=/bin/true
"""
    _write_text(persistence_path, persistence_unit)
    state["persistence"] = {
        "enabled": True,
        "path": str(persistence_path),
        "mode": "demo-only; no host service was modified",
    }
    _append_event(
        event_path,
        {
            "event": "demo_persistence_created",
            "path": str(persistence_path),
        },
    )

    proc_dir = target / "proc"
    proc_dir.mkdir(parents=True, exist_ok=True)
    _write_text(proc_dir / "1001", "name=demo-worker\nvisible=true\n")
    _write_text(proc_dir / "1002", "name=demo-artifact\nvisible=true\n")
    hidden_name = "demo-artifact"
    state["hidden_entries"] = [hidden_name]
    for entry in proc_dir.iterdir():
        if entry.is_file() and hidden_name in entry.read_text(encoding="utf-8"):
            entry.unlink()
    _append_event(
        event_path,
        {
            "event": "demo_process_filter_applied",
            "hidden_entries": state["hidden_entries"],
        },
    )

    state["status"] = "completed"
    state["c2"] = {
        "url": c2_url,
        "attempted": True,
        "result": "unavailable_or_rejected",
    }
    _send_status(
        c2_url,
        {
            "artifact": "benign-demo",
            "status": state["status"],
            "signatures": state["signatures"],
        },
    )

    _write_text(state_path, json.dumps(state, indent=2, sort_keys=True) + "\n")


if __name__ == "__main__":
    try:
        rootkit_polymorphic_system_evasion()
    except Exception as exc:
        try:
