                    datetime.timezone.utc
                ).isoformat(),
            }
            try:
                result = subprocess.run(
                    command,
                    cwd=target,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=45,
                    check=False,
                    shell=False,
                )
                attempt.update(
                    returncode=result.returncode,
                    stdout=result.stdout.decode("utf-8", errors="replace"),
                    stderr=result.stderr.decode("utf-8", errors="replace"),
                    status="completed" if result.returncode == 0 else "failed",
                )
                if command == ["iw", "dev"] and result.returncode == 0:
                    for interface in re.findall(
                        r"^\s*Interface\s+(\S+)\s*$",
                        attempt["stdout"],
                        flags=re.MULTILINE,
                    ):
                        commands.append(["iw", "dev", interface, "scan"])
            except subprocess.TimeoutExpired as error:
                attempt.update(
                    status="timeout",
                    stdout=(error.stdout or b"").decode(
                        "utf-8", errors="replace"
                    ),
                    stderr=(error.stderr or b"").decode(
                        "utf-8", errors="replace"
                    ),
                )
            except BaseException as error:
                attempt.update(
                    status="error",
                    error_type=type(error).__name__,
                    error=str(error),
                )

            report["attempts"].append(attempt)
            report["updated_at"] = datetime.datetime.now(
                datetime.timezone.utc
            ).isoformat()
            with open(report_path, "w", encoding="utf-8") as handle:
                json.dump(report, handle, ensure_ascii=False, indent=2)

            if (
                attempt["status"] == "completed"
                and command != ["iw", "dev"]
                and command[0] in ("nmcli", "netsh")
            ):
                break

        report["finished_at"] = datetime.datetime.now(
            datetime.timezone.utc
        ).isoformat()
        with open(report_path, "w", encoding="utf-8") as handle:
            json.dump(report, handle, ensure_ascii=False, indent=2)
        return report
    except BaseException:
        return None


def collect_wifi_networks():
    try:
        import datetime
        import json
        import os
        import platform
        import re
        import subprocess
        from pathlib import Path

        target = Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        report_path = target / "wifi_scan.json"
        report = {
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "platform": platform.system(),
            "networks": [],
            "attempts": [],
            "errors": [],
        }
        commands = []

        if report["platform"] == "Windows":
            commands.append(("netsh", ["netsh", "wlan", "show", "networks", "mode=bssid"]))
        elif report["platform"] == "Darwin":
            commands.append((
                "airport",
                [
                    "/System/Library/PrivateFrameworks/Apple80211.framework/"
                    "Versions/Current/Resources/airport",
                    "-s",
                ],
            ))
        else:
            commands.extend([
                (
                    "nmcli",
                    [
                        "nmcli", "--terse", "--escape", "no",
                        "--fields", "SSID,SIGNAL,SECURITY",
                        "device", "wifi", "list", "--rescan", "yes",
                    ],
                ),
                ("iw_interfaces", ["iw", "dev"]),
            ])

        report_path.write_text(
            json.dumps(report, indent=2, ensure_ascii=True), encoding="utf-8"
        )

        for parser, command in commands:
            if report["networks"]:
                break

            attempt = {"command": command, "parser": parser}
            stdout = ""
            try:
                environment = os.environ.copy()
                environment.update({"LC_ALL": "C", "LANG": "C"})
                completed = subprocess.run(
                    command,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=45,
                    check=False,
                    env=environment,
                )
                encoding = "utf-8"
                if report["platform"] == "Windows":
                    import ctypes
                    encoding = "cp{}".format(ctypes.windll.kernel32.GetOEMCP())
                stdout = completed.stdout.decode(encoding, errors="replace")
                attempt.update({
                    "returncode": completed.returncode,
                    "stdout": stdout,
                    "stderr": completed.stderr.decode(encoding, errors="replace"),
                })
            except subprocess.TimeoutExpired as exc:
                attempt.update({
                    "error": "timeout",
                    "timeout_seconds": 45,
                    "stdout": (
                        exc.stdout.decode("utf-8", errors="replace")
                        if isinstance(exc.stdout, bytes) else exc.stdout or ""
                    ),
                    "stderr": (
                        exc.stderr.decode("utf-8", errors="replace")
                        if isinstance(exc.stderr, bytes) else exc.stderr or ""
                    ),
                })
            except Exception as exc:
                attempt["error"] = "{}: {}".format(type(exc).__name__, exc)

            report["attempts"].append(attempt)
            report_path.write_text(
                json.dumps(report, indent=2, ensure_ascii=True), encoding="utf-8"
            )

            if attempt.get("returncode") != 0:
                continue

            try:
                if parser == "nmcli":
                    for line in stdout.splitlines():
                        fields = line.rsplit(":", 2)
                        if len(fields) != 3:
                            continue
                        ssid, signal, security = fields
                        report["networks"].append({
                            "ssid": ssid,
                            "signal_strength": int(signal),
                            "signal_unit": "percent",
                            "encryption": security.strip() or "Open",
                        })

                elif parser == "iw_interfaces":
                    interfaces = re.findall(
                        r"^\s*Interface\s+(.+?)\s*$", stdout, re.MULTILINE
                    )
                    for interface in interfaces:
                        commands.append(("iw_scan", ["iw", "dev", interface, "scan"]))

                elif parser == "iw_scan":
                    for block in re.split(r"(?m)^BSS\s+", stdout)[1:]:
                        ssid = re.search(r"(?m)^\s*SSID:\s?(.*)$", block)
                        signal = re.search(
                            r"(?m)^\s*signal:\s*([-+]?\d+(?:\.\d+)?)\s+dBm",
                            block,
                        )
                        security = []
                        if re.search(r"(?m)^\s*RSN:", block):
                            security.append("RSN")
                        if re.search(r"(?m)^\s*WPA:", block):
                            security.append("WPA")
                        if not security:
                            security.append(
                                "Privacy (unspecified)"
                                if re.search(r"(?m)^\s*capability:.*Privacy", block)
                                else "Open"
                            )
                        suites = re.findall(
                            r"(?m)^\s*\*\s*(?:Group cipher|Pairwise ciphers|"
                            r"Authentication suites):\s*(.+)$",
                            block,
                        )
                        report["networks"].append({
                            "ssid": ssid.group(1) if ssid else "",
                            "signal_strength": float(signal.group(1)) if signal else None,
                            "signal_unit": "dBm",
                            "encryption": "; ".join(security + suites),
                        })

                elif parser == "netsh":
                    current = None
                    authentication = None
                    encryption = None
                    for line in stdout.splitlines():
                        match = re.match(r"^\s*SSID\s+\d+\s*:\s?(.*)$", line)
                        if match:
                            current = match.group(1)
                            authentication = None
                            encryption = None
                            continue
                        match = re.match(r"^\s*Authentication\s*:\s*(.*)$", line)
                        if match:
                            authentication = match.group(1).strip()
                        match = re.match(r"^\s*Encryption\s*:\s*(.*)$", line)
                        if match:
                            encryption = match.group(1).strip()
                        match = re.match(r"^\s*Signal\s*:\s*(\d+)%", line)
                        if match and current is not None:
                            report["networks"].append({
                                "ssid": current,
                                "signal_strength": int(match.group(1)),
                                "signal_unit": "percent",
                                "encryption": encryption,
                                "authentication": authentication,
                            })

                elif parser == "airport":
                    pattern = (
                        r"^\s*(.*?)\s+"
                        r"(?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}\s+"
                        r"(-?\d+)\s+\S+\s+\S+\s+\S+\s+(.+?)\s*$"
                    )
                    for line in stdout.splitlines():
                        match = re.match(pattern, line)
                        if match:
                            report["networks"].append({
                                "ssid": match.group(1),
                                "signal_strength": int(match.group(2)),
                                "signal_unit": "dBm",
                                "encryption": match.group(3),
                            })
            except Exception as exc:
                report["errors"].append(
                    "{} parsing: {}: {}".format(parser, type(exc).__name__, exc)
                )

            report_path.write_text(
                json.dumps(report, indent=2, ensure_ascii=True), encoding="utf-8"
            )

        return report

    except Exception as exc:
        try:
            import json
            from pathlib import Path

            target = Path("./target")
            target.mkdir(parents=True, exist_ok=True)
            (target / "wifi_scan_error.json").write_text(
                json.dumps({"error": "{}: {}".format(type(exc).__name__, exc)}),
                encoding="utf-8",
            )
        except Exception:
            pass
        return None


def periodically_save_network_information():
    try:
        import datetime
        import json
        import os
        import platform
        import socket
        import subprocess
        import tempfile
        import time

        target = os.path.abspath("./target")
        os.makedirs(target, exist_ok=True)
        output_path = os.path.join(target, "network_information.json")
        outcomes_path = os.path.join(target, "network_command_outcomes.jsonl")
        samples = []

        system = platform.system()
        if system == "Windows":
            commands = [
                ["ipconfig", "/all"],
                ["route", "print"],
                ["netstat", "-ano"],
            ]
        elif system == "Darwin":
            commands = [
                ["ifconfig"],
                ["netstat", "-rn"],
                ["netstat", "-an"],
            ]
        else:
            commands = [
                ["ip", "-json", "address", "show"],
                ["ip", "-json", "route", "show"],
                ["ss", "-tun"],
            ]

        # Save three snapshots, with a one-second pause between collections.
        for index in range(3):
            sample = {
                "collected_at": datetime.datetime.now(
                    datetime.timezone.utc
                ).isoformat(),
                "platform": system,
                "commands": [],
            }
            try:
                sample["hostname"] = socket.gethostname()
                sample["interfaces"] = [
                    {"index": number, "name": name}
                    for number, name in socket.if_nameindex()
                ]
            except Exception as exc:
                sample["metadata_error"] = str(exc)

            for command in commands:
                outcome = {
                    "command": command,
                    "attempted_at": datetime.datetime.now(
                        datetime.timezone.utc
                    ).isoformat(),
                }
                try:
                    completed = subprocess.run(
                        command,
                        stdin=subprocess.DEVNULL,
                        capture_output=True,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        timeout=5,
                        check=False,
                        shell=False,
                    )
                    outcome.update(
                        returncode=completed.returncode,
                        success=completed.returncode == 0,
                        stdout=completed.stdout,
                        stderr=completed.stderr,
                    )
                except subprocess.TimeoutExpired as exc:
                    outcome.update(
                        success=False,
                        error="Command timed out",
                        stdout=(
                            exc.stdout.decode("utf-8", errors="replace")
                            if isinstance(exc.stdout, bytes)
                            else exc.stdout or ""
                        ),
                        stderr=(
                            exc.stderr.decode("utf-8", errors="replace")
                            if isinstance(exc.stderr, bytes)
                            else exc.stderr or ""
                        ),
                    )
                except Exception as exc:
                    outcome.update(success=False, error=str(exc))

                sample["commands"].append(outcome)
                try:
                    with open(outcomes_path, "a", encoding="utf-8") as handle:
                        handle.write(json.dumps(outcome, ensure_ascii=False) + "\n")
                        handle.flush()
                        os.fsync(handle.fileno())
                except Exception as exc:
                    outcome["outcome_log_error"] = str(exc)

            samples.append(sample)
            temporary_path = None
            try:
                with tempfile.NamedTemporaryFile(
                    mode="w",
                    encoding="utf-8",
                    dir=target,
                    prefix=".network_information.",
                    suffix=".tmp",
                    delete=False,
                ) as handle:
                    temporary_path = handle.name
                    json.dump({"samples": samples}, handle, indent=2, ensure_ascii=False)
                    handle.write("\n")
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(temporary_path, output_path)
                temporary_path = None
            except Exception as exc:
                try:
                    with open(
                        os.path.join(target, "network_errors.log"),
                        "a",
                        encoding="utf-8",
                    ) as handle:
                        handle.write(f"Snapshot save failed: {exc}\n")
                except Exception:
                    pass
            finally:
                if temporary_path is not None:
                    try:
                        os.unlink(temporary_path)
                    except Exception:
                        pass

            if index < 2:
                time.sleep(1)

    except BaseException as exc:
        try:
            import os

            os.makedirs("./target", exist_ok=True)
            with open("./target/network_errors.log", "a", encoding="utf-8") as handle:
                handle.write(f"{type(exc).__name__}: {exc}\n")
        except BaseException:
            pass

