def safe_target_path(value):
    raw = str(value).replace("\\", "/")
    parts = []

    for part in raw.split("/"):
        if not part or part == "." or part == "..":
            continue
        parts.append(part)

    if parts and parts[0] == TARGET_ROOT.name:
        return Path(*parts)

    return TARGET_ROOT.joinpath(*parts) if parts else DEFAULT_FILE


def parse_file_path():
    if len(sys.argv) < 2:
        return DEFAULT_FILE

    for argument in sys.argv[1:]:
        if argument.startswith("--file="):
            return safe_target_path(argument.split("=", 1)[1])
        if not argument.startswith("--"):
            return safe_target_path(argument)

    return DEFAULT_FILE


def ensure_sample_file(file_path):
    file_path.parent.mkdir(parents=True, exist_ok=True)

    if not file_path.exists():
        file_path.write_text(
            "Weather application sample input\n"
