            f"{service_name}.service",
        ]
    elif platform.system().lower().startswith("win"):
        command = ["sc.exe", "query", service_name]
    else:
        command = []

    if not command:
        result_text = "unsupported host service manager; demo state retained"
    else:
        try:
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=3,
                check=False,
