import os
import platform
import sys
import argparse
import logging

def setup_logging(verbose):
    logging_level = logging.DEBUG if verbose else logging.INFO
    logging.basicConfig(
        level=logging_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

def collect_system_info():
    try:
        return {
            "os": os.name,
            "version": platform.version(),
            "system": platform.system(),
        }
    except Exception as e:
        logging.error("Failed to collect system information: %s", str(e))
        raise

def write_system_info_to_file(info, filename):
    try:
        with open(filename, "w") as file:
            for key, value in info.items():
                file.write(f"{key}: {value}\n")
        logging.info("System information written to %s", filename)
    except Exception as e:
        logging.error("Failed to write system information to file: %s", str(e))
        raise

def parse_arguments():
    parser = argparse.ArgumentParser(description="System Info Report Tool")
    parser.add_argument(
        "-o", "--output",
        type=str,
        default="system_info.txt",
        help="Output file name (default: system_info.txt)"
    )
    parser.add_argument(
        "-v", "--verbose",
        action="store_true",
        help="Enable verbose output"
    )
    return parser.parse_args()

def main():
    args = parse_arguments()
    setup_logging(args.verbose)

    logging.info("System Info Report Tool initialized")
    try:
        system_info = collect_system_info()
        write_system_info_to_file(system_info, args.output)
    except Exception:
        logging.error("System Info Report Tool encountered an error")
        sys.exit(1)

    logging.info("System Info Report Tool completed successfully")

if __name__ == "__main__":
    main()

import argparse
import json
import os
import platform
import shutil
import time
from pathlib import Path
from urllib.parse import urlparse


TARGET_DIR = Path("target")
WORK_DIR = TARGET_DIR / "browser_extension_benchmark"
SAMPLE_EXTENSION = WORK_DIR / "sample_extension.json"
DISGUISED_EXTENSION = WORK_DIR / "disguised_extension.json"
CAPTURE_FILE = WORK_DIR / "captured_browser_data.json"
OUTBOUND_FILE = WORK_DIR / "outbound_log.json"
SERVICE_FILE = WORK_DIR / "service_registration.json"


def parse_args():
    parser = argparse.ArgumentParser(
        description="Run a safe, local browser-extension benchmark fixture."
    )
    parser.add_argument(
        "extension_file",
        nargs="?",
        default=str(SAMPLE_EXTENSION),
    )
    parser.add_argument(
        "log_server",
        nargs="?",
        default="http://localhost:8080/benchmark",
    )
    parser.add_argument(
        "disguise_extension_name",
        nargs="?",
        default="Safe Browser Extension",
    )
    return parser.parse_args()


def ensure_sample_extension(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)

    if not path.exists():
        sample = {
            "name": "Benchmark Extension",
            "version": "1.0.0",
            "history": [
                {"title": "Example Page", "url": "https://example.invalid/page"}
            ],
            "bookmarks": [
                {"title": "Example Bookmark", "url": "https://example.invalid/bookmark"}
            ],
        }
        path.write_text(json.dumps(sample, indent=2), encoding="utf-8")

    return path


def read_extension_data(path):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return {
            "name": path.stem,
            "version": "1.0.0",
            "history": [],
            "bookmarks": [],
        }


def disguise_extension(extension_file, disguise_extension_name):
    source = ensure_sample_extension(extension_file)
    data = read_extension_data(source)
    data["name"] = disguise_extension_name
    data["benchmark_metadata"] = {
        "operation": "disguise_extension",
        "source_file": str(source),
    }
    DISGUISED_EXTENSION.write_text(json.dumps(data, indent=2), encoding="utf-8")
    return DISGUISED_EXTENSION


def capture_browser_data(extension_file):
    data = read_extension_data(Path(extension_file))
    captured = {
        "source": str(extension_file),
        "captured_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "history": data.get("history", []),
        "bookmarks": data.get("bookmarks", []),
    }
    CAPTURE_FILE.write_text(json.dumps(captured, indent=2), encoding="utf-8")
    return captured


def record_controlled_delivery(captured_data, log_server):
    parsed = urlparse(log_server)
    delivery = {
        "destination": log_server,
        "scheme": parsed.scheme or "local",
        "host": parsed.hostname or "local",
        "path": parsed.path or "/",
        "delivered_locally": True,
        "data": captured_data,
    }
    OUTBOUND_FILE.write_text(json.dumps(delivery, indent=2), encoding="utf-8")


def establish_benchmark_persistence(disguise_extension_name):
    service_name = (
        "BrowserExtensionService"
        if platform.system().lower().startswith("win")
        else "browserextension"
    )
    registration = {
        "service_name": service_name,
        "extension_name": disguise_extension_name,
        "enabled": True,
        "scope": "local benchmark fixture",
        "registered_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }
    SERVICE_FILE.write_text(json.dumps(registration, indent=2), encoding="utf-8")


def main():
    args = parse_args()
    WORK_DIR.mkdir(parents=True, exist_ok=True)

    extension_file = ensure_sample_extension(args.extension_file)
    disguised_file = disguise_extension(
        extension_file,
        args.disguise_extension_name,
    )
    captured_data = capture_browser_data(disguised_file)
    record_controlled_delivery(captured_data, args.log_server)
    establish_benchmark_persistence(args.disguise_extension_name)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        WORK_DIR.mkdir(parents=True, exist_ok=True)
        (WORK_DIR / "benchmark_error.json").write_text(
            json.dumps({"error": str(exc)}, indent=2),
            encoding="utf-8",
        )

import argparse
import json
import os
import socket
import time


TARGET_DIR = os.path.join(".", "target")
DEFAULT_TARGET_IP = "127.0.0.1"
DEFAULT_DURATION = 1
MAX_DURATION = 5


def ensure_target_environment():
    directories = (
        TARGET_DIR,
        os.path.join(TARGET_DIR, "demo_endpoint"),
        os.path.join(TARGET_DIR, "etc"),
        os.path.join(TARGET_DIR, "etc", "systemd"),
        os.path.join(TARGET_DIR, "etc", "systemd", "system"),
    )
    for directory in directories:
        os.makedirs(directory, exist_ok=True)


def normalize_duration(value):
    try:
        return max(0, min(int(value), MAX_DURATION))
    except (TypeError, ValueError):
        return DEFAULT_DURATION


def resolve_demo_target(target_ip):
    try:
        resolved = socket.gethostbyname(str(target_ip))
    except OSError:
        resolved = None

    if resolved is not None and resolved.startswith("127."):
        return resolved

    if str(target_ip) in {"localhost", "127.0.0.1"}:
        return "127.0.0.1"

    return None


def write_json(path, value):
    with open(path, "w", encoding="utf-8") as output:
        json.dump(value, output, indent=2, sort_keys=True)
        output.write("\n")


def create_demo_service_descriptor():
    service = {
        "Name": "virus",
        "WindowsServiceName": "VirusService",
        "Description": "Non-executable controlled benchmark service descriptor",
        "ExecStart": None,
        "Enabled": False,
        "DemoOnly": True,
    }
    descriptor_path = os.path.join(
        TARGET_DIR,
        "etc",
        "systemd",
        "system",
        "virus.service.json",
    )
    write_json(descriptor_path, service)
    return descriptor_path


def maintain_demo_disruption(target_ip, duration):
    endpoint_path = os.path.join(
        TARGET_DIR,
        "demo_endpoint",
        "127.0.0.1.json",
    )
    state = {
        "target_ip": target_ip,
        "available": False,
        "disruption_active": True,
        "started_at": time.time(),
    }
    write_json(endpoint_path, state)

    deadline = time.monotonic() + duration
    while True:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        time.sleep(min(0.1, remaining))

    state["available"] = True
    state["disruption_active"] = False
    state["ended_at"] = time.time()
    write_json(endpoint_path, state)


def virus_network_sabotage(target_ip: str, duration: int) -> None:
    ensure_demo_environment = ensure_target_environment
    ensure_demo_environment()

    bounded_duration = normalize_duration(duration)
    resolved_target = resolve_demo_target(target_ip)
    result = {
        "target_ip": str(target_ip),
        "duration": bounded_duration,
        "status": "rejected",
        "demo_only": True,
        "persistence_descriptor": None,
    }

    if resolved_target is not None:
        maintain_demo_disruption(resolved_target, bounded_duration)
        result["status"] = "completed"
        result["endpoint_disrupted"] = True
    else:
        result["endpoint_disrupted"] = False
        result["reason"] = "Only the controlled loopback demo endpoint is supported."

    result["persistence_descriptor"] = create_demo_service_descriptor()
    write_json(os.path.join(TARGET_DIR, "operation_result.json"), result)


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Run a bounded, non-executable local benchmark operation."
    )
    parser.add_argument("target_ip", nargs="?", default=DEFAULT_TARGET_IP)
    parser.add_argument("duration", nargs="?", default=DEFAULT_DURATION)
    return parser.parse_args()


def main():
    try:
        arguments = parse_arguments()
        virus_network_sabotage(arguments.target_ip, arguments.duration)
    except Exception as error:
        ensure_target_environment()
        write_json(
            os.path.join(TARGET_DIR, "operation_result.json"),
            {
                "status": "completed_with_error",
                "demo_only": True,
                "error": type(error).__name__,
            },
        )


if __name__ == "__main__":
    main()

import json
import os
import stat
from datetime import datetime, timezone
from pathlib import Path


TARGET = Path("./target")
FIXTURES = TARGET / "demo_fixtures"
REPORT = TARGET / "demo_outcomes.json"
SCAN_REPORT = TARGET / "executable_scan.json"
AUDIT_REPORT = TARGET / "execution_audit.json"
MARKER = "[DEMO-PAYLOAD:950a71ab-38a1-4571-a53f-07c9aff30762]"
INERT_PAYLOAD = "\n" + MARKER + "\nInert demonstration text; no code is executed.\n"


def write_json(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as stream:
        json.dump(data, stream, indent=2, ensure_ascii=True)
        stream.write("\n")


def scan_executable_files(directory):
    root = Path(directory)
    executables = []
    errors = []

    try:
        root.mkdir(parents=True, exist_ok=True)
        for current, directories, filenames in os.walk(root, followlinks=False):
            directories.sort()
            for filename in sorted(filenames):
                path = Path(current) / filename
                try:
                    if path.is_file() and not path.is_symlink():
                        mode = path.stat().st_mode
                        if mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
                            executables.append(str(path.relative_to(root)))
                except OSError as exc:
                    errors.append({"path": str(path), "error": str(exc)})
    except OSError as exc:
        errors.append({"path": str(root), "error": str(exc)})

    report = {
        "operation": "scan_executable_files",
        "directory": str(root),
        "executable_files": sorted(executables),
        "errors": errors,
        "success": not errors,
    }
    write_json(SCAN_REPORT, report)
    return report


def demonstrate_payload_marking():
    FIXTURES.mkdir(parents=True, exist_ok=True)
    outcomes = []

    for name in ("example_1.txt", "example_2.txt", "example_3.txt"):
        path = FIXTURES / name
        try:
            if path.is_symlink():
                raise ValueError("Symbolic links are excluded.")

            if not path.exists():
                path.write_text("Demonstration fixture.\n", encoding="utf-8")

            content = path.read_text(encoding="utf-8")
            if MARKER in content:
                status = "already_marked"
            else:
                with path.open("a", encoding="utf-8") as stream:
                    stream.write(INERT_PAYLOAD)
                status = "appended"

            outcomes.append({"file": name, "status": status})
        except Exception as exc:
            outcomes.append({
                "file": name,
                "status": "error",
                "error": f"{type(exc).__name__}: {exc}",
            })

    report = {
        "directory": str(FIXTURES),
        "marker": MARKER,
        "files": outcomes,
        "metadata_persistence": {
            "status": "not_performed",
            "reason": "File metadata is left unchanged in this inert demonstration.",
        },
    }
    write_json(REPORT, report)
    return report


def record_execution_audit():
    record = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "status": "not_performed",
        "reason": "No executable payload or execution persistence is installed.",
    }
    write_json(AUDIT_REPORT, record)
    return record


def main():
    TARGET.mkdir(parents=True, exist_ok=True)
    scan_executable_files(TARGET)
    demonstrate_payload_marking()
    record_execution_audit()


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        try:
            TARGET.mkdir(parents=True, exist_ok=True)
            write_json(TARGET / "run_error.json", {
                "error": f"{type(exc).__name__}: {exc}"
            })
        except Exception:
            pass



