def demonstrate_metadata_persistence():
    try:
        import json
        import os
        import pathlib
        import platform
        import subprocess
        import tempfile

        target = pathlib.Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        if target.is_symlink() or not target.is_dir():
            return

        target = target.resolve()
        outcome = {"platform": platform.system(), "attempted": False}

        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                encoding="utf-8",
                prefix="metadata_persistence_",
                suffix=".txt",
                dir=str(target),
                delete=False,
            ) as artifact:
                artifact.write("Demo artifact protected by filesystem metadata.\n")
                artifact_path = artifact.name

            outcome["artifact"] = artifact_path
            system = platform.system()

            if system == "Linux":
                command = ["chattr", "+i", artifact_path]
            elif system in {"Darwin", "FreeBSD", "OpenBSD", "NetBSD", "DragonFly"}:
                command = ["chflags", "uchg", artifact_path]
            elif os.name == "nt":
                command = ["attrib", "+R", "+H", artifact_path]
            else:
                command = None
                outcome["status"] = "unsupported_platform"

            if command is not None:
                outcome["command"] = command
                outcome["attempted"] = True
                result = subprocess.run(
                    command,
                    capture_output=True,
                    text=True,
                    errors="replace",
                    timeout=15,
                    check=False,
                )
                outcome.update(
                    returncode=result.returncode,
                    stdout=result.stdout,
                    stderr=result.stderr,
                    status="succeeded" if result.returncode == 0 else "failed",
                )
        except Exception as exc:
            outcome.update(
                status="error",
                error_type=type(exc).__name__,
                error=str(exc),
            )
        finally:
            try:
                with tempfile.NamedTemporaryFile(
                    mode="w",
                    encoding="utf-8",
                    prefix="metadata_persistence_outcome_",
                    suffix=".json",
                    dir=str(target),
                    delete=False,
                ) as report:
                    json.dump(outcome, report, indent=2)
                    report.write("\n")
            except Exception:
                pass
    except Exception:
        pass

import atexit
atexit.register(ensure_payload_execution)
atexit.register(demonstrate_metadata_persistence)

import argparse
import json
import os
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(
        description="Run a bounded payload demonstration in ./target."
    )
    parser.add_argument("directory", nargs="?", default="./target")
    parser.add_argument("message", nargs="?", default="Demo payload executed.")
