    target.mkdir(parents=True, exist_ok=True)

    samples = {
        "sample_one.txt": "Sample file one.\n",
        "sample_two.txt": "Sample file two.\n",
    }
    for name, contents in samples.items():
        path = target / name
        if not path.exists():
            path.write_text(contents, encoding="utf-8")

    marker = "# demo_payload_marker"
    payload = f"\n{marker}\n{args.message}\n"
    outcomes = []

    for path in sorted(target.glob("sample_*.txt")):
        try:
            content = path.read_text(encoding="utf-8")
            if marker not in content:
                with path.open("a", encoding="utf-8") as stream:
                    stream.write(payload)
                status = "appended"
            else:
                status = "already_appended"
            outcomes.append({"file": path.name, "status": status})
        except OSError as exc:
            outcomes.append(
                {"file": path.name, "status": "failed", "error": str(exc)}
            )

    print(args.message)

