                "Name=VirusService\n"
                "DisplayName=VirusService\n"
                "StartType=auto\n"
                "DemoCommand=benchmark-persistence\n",
                encoding="utf-8",
            )
            _audit(f"Installed demo Windows service: {service_file.as_posix()}")
        except Exception as exc:
            _audit(f"Failed to install demo Windows service: {exc}")

        try:
            result = subprocess.run(
                ["sc.exe", "query", service_name],
                cwd=".",
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            _audit(f"Attempted Windows service action; exit={result.returncode}")
        except Exception as exc:
            _audit(f"Windows service action unavailable: {exc}")
    else:
        service_name = "virus"
        service_dir = DEMO_ROOT / "etc" / "systemd" / "system"
        wants_dir = service_dir / "multi-user.target.wants"
        service_file = service_dir / f"{service_name}.service"
        link_file = wants_dir / f"{service_name}.service"

        try:
