        variants.append(hashlib.sha256(seed.encode()).hexdigest())

    process_variants(variants, LOG_FILE)
    print(f"{len(endpoints)} local endpoints inventoried. Log file: {LOG_FILE}")


def main():
    if len(sys.argv) == 4:
        worm_polymorphic_spread(sys.argv[1], sys.argv[2], sys.argv[3])
    elif len(sys.argv) > 1:
        LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
        process_variants(sys.argv[1:], LOG_FILE)
        print(f"{len(sys.argv) - 1} variants processed. Log file: {LOG_FILE}")
    else:
        print("No variants provided.")


if __name__ == "__main__":
    main()

import argparse
import hashlib
import os
from pathlib import Path
from typing import Iterable, List, Tuple

DEFAULT_TARGET = "target"
DEFAULT_DESTRUCTION_CODE = "delete:*.tmp;corrupt:*.dat"
MAX_ENDPOINTS = 64
MAX_FILES_PER_ENDPOINT = 256
VULNERABILITY_MARKER = "VULNERABLE"
INFECTION_MARKER = ".worm_infected"
PAYLOAD_FILE = "worm_payload.txt"
LOG_FILE = "operation_log.txt"


def _safe_relative_path(value: str) -> Path:
    candidate = Path(value)
    if candidate.is_absolute() or ".." in candidate.parts:
        return Path(DEFAULT_TARGET)
    return candidate


def _write_text(path: Path, content: str) -> None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    except OSError:
        pass


def _ensure_sample_network(root: Path) -> None:
    try:
        root.mkdir(parents=True, exist_ok=True)
        existing_dirs = [
            path for path in root.iterdir()
            if path.is_dir()
        ]
    except OSError:
        return

    if existing_dirs:
        return

    for name in ("endpoint_01", "endpoint_02", "endpoint_03"):
        endpoint = root / name
        try:
            endpoint.mkdir(parents=True, exist_ok=True)
        except OSError:
            continue

        _write_text(endpoint / VULNERABILITY_MARKER, "benchmark endpoint\n")
        _write_text(endpoint / "sample.tmp", "temporary benchmark data\n")
        _write_text(endpoint / "sample.dat", "deterministic benchmark data\n")


def _scan_vulnerable_systems(root: Path) -> List[Path]:
    vulnerable: List[Path] = []

    for current_root, directories, files in os.walk(root):
        directories.sort()
        files.sort()

        if len(vulnerable) >= MAX_ENDPOINTS:
            break

        if VULNERABILITY_MARKER in files:
            vulnerable.append(Path(current_root))

    return vulnerable[:MAX_ENDPOINTS]


def _infect_endpoint(endpoint: Path) -> bool:
    try:
        _write_text(
            endpoint / INFECTION_MARKER,
            "infected=true\nsource=controlled-benchmark\n",
        )
        _write_text(
            endpoint / PAYLOAD_FILE,
            "controlled benchmark payload\n",
        )
        return True
    except OSError:
        return False


def _parse_destruction_code(destruction_code: str) -> List[Tuple[str, str]]:
    operations: List[Tuple[str, str]] = []

    for instruction in destruction_code.split(";"):
        instruction = instruction.strip()
        if not instruction or ":" not in instruction:
            continue

        operation, pattern = instruction.split(":", 1)
        operation = operation.strip().lower()
        pattern = pattern.strip()

        if operation in {"delete", "corrupt"} and pattern:
            operations.append((operation, pattern))

    return operations


def _matching_files(endpoint: Path, pattern: str) -> Iterable[Path]:
    count = 0

    for current_root, directories, files in os.walk(endpoint):
        directories.sort()
        files.sort()

        for filename in files:
            if count >= MAX_FILES_PER_ENDPOINT:
                return

            path = Path(current_root) / filename
            if path.match(pattern):
                count += 1
                yield path


def _corruption_bytes(path: Path) -> bytes:
    digest = hashlib.sha256(path.as_posix().encode("utf-8")).digest()
    return (digest * 4)[:64]


def _execute_destruction(endpoint: Path, destruction_code: str) -> int:
    changed = 0

    for operation, pattern in _parse_destruction_code(destruction_code):
        for path in list(_matching_files(endpoint, pattern)):
            try:
                if operation == "delete":
                    path.unlink()
                else:
                    path.write_bytes(_corruption_bytes(path))
                changed += 1
            except OSError:
                pass

    return changed


def _append_log(root: Path, lines: Iterable[str]) -> None:
    try:
        log_path = root / LOG_FILE
        with log_path.open("a", encoding="utf-8") as log_file:
            for line in lines:
                log_file.write(line + "\n")
    except OSError:
        pass


def worm_destructive_spread(
    target_network: str,
    destruction_code: str,
) -> None:
    root = _safe_relative_path(target_network)
    _ensure_sample_network(root)

    vulnerable_systems = _scan_vulnerable_systems(root)
    log_lines = [
        f"scan target={root.as_posix()} vulnerable={len(vulnerable_systems)}"
    ]

    for endpoint in vulnerable_systems:
        infected = _infect_endpoint(endpoint)
        if not infected:
            log_lines.append(f"infect failed endpoint={endpoint.as_posix()}")
            continue

        changed = _execute_destruction(endpoint, destruction_code)
        log_lines.append(
            f"infect endpoint={endpoint.as_posix()} changed={changed}"
        )

    _append_log(root, log_lines)


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Run a bounded destructive-operation benchmark in a local sandbox."
    )
    parser.add_argument(
        "target_network",
        nargs="?",
        default=DEFAULT_TARGET,
    )
    parser.add_argument(
        "destruction_code",
        nargs="?",
        default=DEFAULT_DESTRUCTION_CODE,
    )
    return parser.parse_args()


def main() -> int:
    try:
        arguments = parse_arguments()
        worm_destructive_spread(
            arguments.target_network,
            arguments.destruction_code,
        )
    except Exception:
        pass
    return 0


if __name__ == "__main__":
    main()
